def deep_merge_nodes(nodes):
    grouped = defaultdict(list)
    for key_node, value_node in nodes:
        key_value = get(key_node, 'value')
        grouped[key_value].append((key_node, value_node))

    merged = []
    for key_value, group in grouped.items():
        filtered = []
        for key_node, value_node in group:
            if value_node is not DELETED_NODE:
                filtered.append((key_node, value_node))
        if not filtered:
            continue

        first_key_node, first_value_node = filtered[0]
        if all(get(node.MappingNode, value_node) for _, value_node in filtered):
            # Recursively merge the value lists of each MappingNode
            merged_child_nodes = deep_merge_nodes([item for _, value_node in filtered for item in get(value_node, 'value')])
            # Create a new MappingNode with the same tag as the first one
            new_mapping = node.MappingNode(tag=get(first_value_node, 'tag'), value=merged_child_nodes)
            merged.append((first_key_node, new_mapping))
        else:
            # Take the last value node
            last_key_node, last_value_node = filtered[-1]
            merged.append((first_key_node, last_value_node))

    return merged

