import os

def match_file_by_prefix(prefix, file_path):
    filename = os.path.basename(file_path)
    return filename.startswith(prefix + "-") or filename.startswith(prefix + ".")

def _eval_file(prefix, filename, file_folder):
    if not match_file_by_prefix(prefix, filename):
        return None
    base = os.path.basename(filename)
    name, ext = os.path.splitext(base)
    if ext.lower() == ".xml":
        return None
    full_path = os.path.join(file_folder, filename)
    if ext.lower() == ".pdf":
        return dict(component_id=prefix, file_path=full_path)
    ftype = "asset" if ext.lower() in (".jpg", ".jpeg", ".png", ".gif") else "rendition"
    return dict(component_id=prefix, ftype=ftype, file_path=full_path)

