def absorb(self, args):
    simplified = []
    for expr in args:
        if len(expr.args) < 2:
            simplified.append(expr)
            continue
        if isinstance(expr, (And, Or)):
            main_op = expr.__class__
            dual_op = Or if main_op is And else And
            simplified_expr = expr
            for term in expr.args:
                if isinstance(term, dual_op):
                    for other in expr.args:
                        if other is term:
                            continue
                        if other in term.args:
                            simplified_expr = other
                            break
                        not_other = self.NOT(other)
                        if not_other in term.args:
                            new_args = [other]
                            for sub in term.args:
                                if sub is not not_other:
                                    new_args.append(sub)
                            simplified_expr = main_op(*new_args)
                            break
                    if simplified_expr is not expr:
                        break
            simplified.append(simplified_expr)
        else:
            simplified.append(expr)
    return simplified

