    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        else:
            val1 = d1[key]
            val2 = d2[key]
            current_level = level
            if current_level == -1:
                next_level = -1
            else:
                next_level = current_level - 1
            if current_level == 1:
                if val1 != val2:
                    result[key] = val1
            else:
                if isinstance(val1, dict) and isinstance(val2, dict):
