def _fromutc(self, dt):
    if not dt.tzinfo is self:
        raise ValueError("Naive time - no tzinfo set")

    offset = self.utcoffset(dt)
    if offset is None:
        return dt.replace(tzinfo=self)

    dtdim = dt - offset
    dst = self.dst(dtdim)
    if dst is None:
        dtdim = dtdim.enfold()

    return dtdim.replace(tzinfo=self)

