def int_to_string(number, alphabet, padding=None):
    if number == 0:
        if padding is None or padding == 0:
            return alphabet[0]
        else:
            return alphabet[0] * padding
    base = len(alphabet)
    digits = []
    while number > 0:
        number, remainder = divmod(number, base)
        digits.append(alphabet[remainder])
    digits.reverse()
    if padding is not None:
        digits = [alphabet[0]] * (padding - len(digits)) + digits
    return ''.join(digits)

