def merge_extra_vars(vars_dict, extra_vars):
    from yaml import safe_load
    from exceptions import IRExtraVarsException
    from dict_utils import dict_merge, dict_insert, unique_append_list_resolver

    for extra_var in extra_vars:
        if extra_var.startswith('---'):
            try:
                data = safe_load(extra_var)
            except Exception as e:
                raise IRExtraVarsException(f"Failed to parse YAML: {extra_var}") from e
            dict_merge(vars_dict, data)
        else:
            parts = extra_var.split('=', 1)
            if len(parts) != 2:
                raise IRExtraVarsException(f"Invalid key=value format: {extra_var}")
            key, value = parts
            dict_insert(vars_dict, key, value, resolver=unique_append_list_resolver)

