        option_spec = self.spec_helper.get_option_spec(parser_name, key)
        if option_spec and "type" in option_spec:
            type_func = {
                "int": int,
                "bool": lambda x: x.lower() == "true"
            }.get(option_spec["type"].lower(), str)
            try:
                values_dict[key] = type_func(value)
            except (ValueError, TypeError):
                pass

def get_plugin_spec_flatten_dict(plugin_dir):
    path = os.path.join(plugin_dir, PLUGIN_SPEC)
    with open(path, 'r') as f:
        spec_yaml = yaml.safe_load(f)
    flat_dict = {}

    def _flatten(prefix, obj):
        if isinstance(obj, dict):
            keys_list = list(obj.keys())
            for key in keys_list:
                new_prefix = f"{prefix}.{key}" if prefix else key
                _flatten(new_prefix, obj[key])
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                new_prefix = f"{prefix}[{idx}]"
                _flatten(new_prefix, item)
        else:
            flat_dict[prefix] = obj

    _flatten('', spec_yaml)
    return flat_dict

