def identify_request(request):
    body = request.body
    decoded_body = decode_if_bytes(body)
    json_events = False
    try:
        json_data = json.loads(decoded_body)
        json_events = 'events' in json_data
    except json.JSONDecodeError:
        pass

    xml_tag_matches = False
    try:
        xml_root = fromstring(decoded_body)
        xml_tag_matches = xml_root.tag == MAGIC_ENV_TAG
    except etree.ParseError:
        pass

    return json_events or xml_tag_matches

def find_tags(text, replacer=None):
    tags = set()
    processed_lines = []
    code_block = False
    for line in text.splitlines():
        if line.startswith('```'):
            code_block = not code_block
            processed_lines.append(line)
            continue
        if code_block:
            processed_lines.append(line)
        else:
            words = line.split()
            new_words = []
            for word in words:
                if test_tag(word):
                    tags.add(word)
                    if replacer:
                        new_words.append(replacer(word))
                    else:
                        new_words.append(word)
                else:
                    new_words.append(word)
            processed_lines.append(' '.join(new_words))
    modified_text = '\n'.join(processed_lines)
    return tags, modified_text

