def try_retrieve_webfinger_document(handle):
    try:
        local_part, host = handle.split('@')
        path = "/.well-known/webfinger"
        quoted_handle = quote(handle)
        url = f"https://{host}{path}?resource=acct:{quoted_handle}"
        response = fetch_document(
            url=url,
            host=host,
            path=path,
            timeout=10,
            raise_ssl_errors=True,
            extra_headers={'User-Agent': USER_AGENT}
        )
        if response.status_code == 200:
            return response.text
    except Exception as ex:
        logger.warning("Failed to retrieve webfinger document", exc_info=ex)
    return None
